from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class CrossSectionalMomentum(Strategy):
    rationale = (
        "Cross-sectional momentum exploits the tendency for assets that have performed "
        "well recently to continue outperforming over a short horizon. This phenomenon can be "
        "attributed to various factors including investor behavior and market sentiment."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        closes = view.closes(lookback=self._window)
        if closes.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        momentum_scores = {}
        for symbol in view.symbols:
            if symbol not in closes.columns:
                continue
            values = [float(v) for v in closes[symbol].drop_nulls().to_list()]
            if len(values) < self._window:
                continue

            # Calculate the return over the window period
            returns = [(values[i] / values[i - 1] - 1.0) for i in range(1, self._window)]
            momentum_score = sum(returns) / (self._window - 1)

            if not np.isnan(momentum_score):
                momentum_scores[symbol] = momentum_score

        # Sort symbols by their momentum scores
        sorted_symbols = [
            s for _, s in sorted(momentum_scores.items(), key=lambda item: item[1], reverse=True)
        ]

        if not sorted_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(sorted_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in sorted_symbols},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
